import { formatMoney, formatPercentage } from '../../helpers/utility'

const PACKAGE_TYPE_LABEL = {
  'car-protection-comprehensive': 'Komprehensif',
  'car-protection-tlo': 'TLO',
}

// Calc methods whose `percentage` is already expressed in percent units (0.1 => 0.1%).
// Every other method returns a decimal fraction (0.00075 => 0.075%).
const ABSOLUTE_PERCENT_METHODS = ['p_calc', 'conditional']

const resolvePCalcPercentage = (percentageObj, sumInsured, { vehicleType, usage }) => {
  const usageData = percentageObj?.[vehicleType]?.[usage]
  if (!usageData) return 0
  if (usageData[String(sumInsured)]) return usageData[String(sumInsured)]
  const keys = Object.keys(usageData)
    .map(Number)
    .sort((a, b) => a - b)
  const matchingKey = keys.find((key) => key >= sumInsured)
  if (matchingKey) return usageData[String(matchingKey)]
  return keys.length > 0 ? usageData[String(keys[keys.length - 1])] : 0
}

// Resolves brand_variant_type_year_based_calc conditional percentages.
// Keys in the ranges represent vehicle age thresholds (e.g. "5" = up to 5 yrs old).
const resolveConditionalPercentage = (
  percentageObj,
  policyYear,
  { vehicleType, brandCode, manufactureYear, startYear }
) => {
  if (percentageObj?.condition === 'year_range_based_calc') {
    const yearRanges = percentageObj.year_ranges || {}
    if (!yearRanges) return 0
    // Vehicle age at the start of this policy year
    const vehicleAge = startYear + policyYear - 1 - manufactureYear
    const keys = Object.keys(yearRanges)
      .map((a) => Number(a))
      .sort((a, b) => a - b)
    const matchingKey = keys.find((key) => key >= vehicleAge)
    return matchingKey ? yearRanges[String(matchingKey)] : yearRanges['inf']
  }
  if (percentageObj?.condition === 'brand_variant_type_year_based_calc') {
    const ranges = percentageObj.brand_variant_type_year_based_ranges || {}
    // Use exact brand match, otherwise fall back to "others"
    const brandRanges = ranges[brandCode] || ranges.others
    const vehicleTypeRanges = brandRanges?.[vehicleType]
    if (!vehicleTypeRanges) return 0
    // Vehicle age at the start of this policy year
    const vehicleAge = startYear + policyYear - 1 - manufactureYear
    const keys = Object.keys(vehicleTypeRanges)
      .map(Number)
      .sort((a, b) => a - b)
    const matchingKey = keys.find((key) => key >= vehicleAge)
    return matchingKey ? vehicleTypeRanges[String(matchingKey)] : 0
  }
  return 0
}

const resolveAddonPercentage = (addon, policyYear, context) => {
  if (typeof addon.percentage === 'number') return addon.percentage
  if (addon.calc_method === 'p_calc' && addon.percentage && !addon.percentage.condition) {
    return resolvePCalcPercentage(addon.percentage, Number(addon.sum_insured) || 0, context)
  }
  if (addon.calc_method === 'conditional' && addon.percentage?.condition) {
    return resolveConditionalPercentage(addon.percentage, policyYear, context)
  }
  return 0
}

// `breakup` follows the premium_breakup shape: { sum_insured, percent, premium }
const buildBreakupRow = (key, label, breakup, alwaysVisible = false) => ({
  key,
  label,
  alwaysVisible,
  premium: Number(breakup?.premium) || 0,
  sumInsured: Number(breakup?.sum_insured) || 0,
  percentage: Number(breakup?.percent) || 0,
  isDecimalPercent: false,
  sumInsuredOnly: false,
})

const buildAddonRow = (addon, policyYear, context) => {
  const percentage = resolveAddonPercentage(addon, policyYear, context)
  return {
    key: addon.add_on_code,
    label: addon.add_on_name,
    alwaysVisible: true,
    premium: Number(addon.premium) || 0,
    sumInsured: Number(addon.sum_insured) || 0,
    percentage,
    isDecimalPercent: !ABSOLUTE_PERCENT_METHODS.includes(addon.calc_method),
    // Conditional addons can fail to resolve a rate; then only the sum insured is shown
    sumInsuredOnly: addon.calc_method === 'conditional' && !percentage,
  }
}

export const getCalcLabel = ({ sumInsured, percentage, isDecimalPercent, sumInsuredOnly }) => {
  const sumInsuredLabel = `${formatMoney(sumInsured ?? 0, 0)}*`
  if (sumInsuredOnly) return `(${sumInsuredLabel})`
  return `(${sumInsuredLabel} x ${formatPercentage(percentage ?? 0)})`
}

/**
 * Flattens each policy year into a single ordered list of rows
 * (Premi Dasar, Loading Rate, then every applicable addon) so the UI can render
 * them with one loop instead of special-casing the base premium.
 */
export const buildYearWiseBreakdown = (policyDetails = {}) => {
  const context = {
    vehicleType: policyDetails.vehicle_type || '',
    usage: policyDetails.usage || '',
    brandCode: policyDetails.brand_code || '',
    manufactureYear: policyDetails.year || 0,
    startYear: policyDetails.start_date
      ? new Date(policyDetails.start_date).getFullYear()
      : new Date().getFullYear(),
  }

  const packageTypeByYear = new Map(
    (policyDetails.year_based_package_type_map || []).map((item) => [
      Number(item.year),
      item.package_type,
    ])
  )
  const premiumBreakup = policyDetails.package_data?.premium_breakup || {}

  return (policyDetails.package_data?.multiyear_addons_data || []).map((yearData) => {
    const { year, addons_applicable: addonsApplicable = [] } = yearData
    const yearBreakup = premiumBreakup[year] || {}
    const typeLabel = PACKAGE_TYPE_LABEL[packageTypeByYear.get(Number(year))] || ''

    const rows = [
      buildBreakupRow('base_premium', 'Premi Dasar', yearBreakup.base_premium, true),
      buildBreakupRow('accessory_premium', 'Premi Aksesoris', yearBreakup.accessory_premium),
      buildBreakupRow('loading_premium', 'Loading Rate', yearBreakup.loading_premium),
      ...addonsApplicable.map((addon) => buildAddonRow(addon, year, context)),
    ].filter((row) => row.alwaysVisible || row.premium > 0)

    return {
      year,
      title: `Rincian Tahun ${year}${typeLabel ? ` (${typeLabel})` : ''}`,
      rows,
      subTotal: rows.reduce((sum, row) => sum + row.premium, 0),
    }
  })
}

export const getFees = (policyDetails = {}) =>
  policyDetails?.package_data?.fees || []

export const getDiscount = (policyDetails = {}, appliedDiscount) =>
  appliedDiscount ?? policyDetails?.discount ?? 0

export const getTotalBill = (policyDetails = {}, appliedDiscount) =>
  (policyDetails?.package_data?.total_bill ?? 0) -
  (appliedDiscount ?? policyDetails?.discount ?? 0)
