import { formatMoney } from '../../helpers/utility'
import { LANG_STRINGS } from '../../lang'
import RadioV2 from '../RadioV2'
import { DISCOUNT_TYPE } from './hooks'
import { DiscountHeader, DiscountInputWrapper, Hr1 } from './index.style'

const DISCOUNT_TYPE_OPTIONS = [
  { value: DISCOUNT_TYPE.NOMINAL, name: LANG_STRINGS.nominalNew },
  { value: DISCOUNT_TYPE.PERCENTAGE, name: LANG_STRINGS.percentageNew },
]

const NominalInput = ({ amount, hasError, maxDiscount, onChange }) => (
  <div className="nominal-wrapper">
    <div className={`discount-input-display ${hasError ? 'error-ctn' : ''}`}>
      <span>Rp</span>
      <input
        className="discount-input-area"
        onChange={onChange}
        value={amount || ''}
        inputMode="numeric"
        data-testid="discount-nominal-input"
      />
    </div>
    <div className="nominal-max-discount">
      {`MAKS. ${formatMoney(maxDiscount, 0, 'Rp')}`}
    </div>
  </div>
)

const PercentageInput = ({
  amount,
  percent,
  hasError,
  maxDiscountPercent,
  onChange,
}) => (
  <div className="discount-wrapper">
    <div className="discount-input-display-percent">
      <div className={`discount-wrapper-percent-input ${hasError ? 'error-ctn' : ''}`}>
        <input
          className="discount-input-area-error"
          onChange={onChange}
          value={percent || ''}
          inputMode="numeric"
          data-testid="discount-percentage-input"
        />
        <span>%</span>
      </div>
      <div className={`discount-input-area-error-disabled ${hasError ? 'error-ctn' : ''}`}>
        {formatMoney(isNaN(amount) ? 0 : amount, 0, 'Rp')}
      </div>
    </div>
    <div className="nominal-max-discount">{`MAKS. ${maxDiscountPercent}%`}</div>
  </div>
)

/**
 * Editable mode always renders, so an agent can still add a discount when none
 * is set yet. Static mode is only worth showing once a discount exists.
 */
const DiscountEditSection = ({
  discount = 0,
  maxDiscount = 0,
  maxDiscountPercent = 0,
  discountInput,
}) => {
  const { isExpanded, toggle, type, changeType, amount, percent, hasError, handleInputChange } =
    discountInput

  return (
    <>
      <Hr1 />
      <DiscountHeader isOpen={isExpanded} data-testid="discount-row">
        <div>{LANG_STRINGS.discount}</div>
        <div
          className="discount-toggle"
          onClick={toggle}
          data-testid="discount-toggle"
        >
          {isExpanded ? 'x' : '+'}
        </div>
      </DiscountHeader>
      {isExpanded && (
        <DiscountInputWrapper>
          <RadioV2
            data={DISCOUNT_TYPE_OPTIONS}
            defaultValue={type}
            titleSize="0.7em"
            name="discount_type"
            className="discount-radio-display"
            onChange={changeType}
          />
          {type === DISCOUNT_TYPE.NOMINAL ? (
            <NominalInput
              amount={amount}
              hasError={hasError}
              maxDiscount={maxDiscount}
              onChange={handleInputChange}
            />
          ) : (
            <PercentageInput
              amount={amount}
              percent={percent}
              hasError={hasError}
              maxDiscountPercent={maxDiscountPercent}
              onChange={handleInputChange}
            />
          )}
        </DiscountInputWrapper>
      )}
    </>
  )
}

export default DiscountEditSection
